export const PRIORITIES = ['low', 'normal', 'high'] as const

export type Priority = (typeof PRIORITIES)[number]

export type Task = {
  id: string
  title: string
  completed: boolean
  priority: Priority
  createdAt: string
  updatedAt: string
}

export type CreateTaskInput = {
  title: string
  completed?: boolean
  priority?: Priority
}

export type UpdateTaskInput = {
  title?: string
  completed?: boolean
  priority?: Priority
}

/** Filter applied by {@link TaskStore.list}. An empty object matches every task. */
export type TaskFilter = {
  completed?: boolean
  priority?: Priority
}

/**
 * In-memory task storage. A class (rather than module-level state) so that
 * every app instance — in particular every test — starts from a clean slate.
 */
export class TaskStore {
  #tasks = new Map<string, Task>()
  #nextId = 1

  list(filter: TaskFilter): Task[] {
    return [...this.#tasks.values()].filter((task) => {
      if (filter.completed !== undefined && task.completed !== filter.completed) return false
      if (filter.priority !== undefined && task.priority !== filter.priority) return false
      return true
    })
  }

  get(id: string): Task | undefined {
    return this.#tasks.get(id)
  }

  create(input: CreateTaskInput): Task {
    const now = new Date().toISOString()
    const task: Task = {
      id: String(this.#nextId++),
      title: input.title,
      completed: input.completed ?? false,
      priority: input.priority ?? 'normal',
      createdAt: now,
      updatedAt: now,
    }
    this.#tasks.set(task.id, task)
    return task
  }

  update(id: string, input: UpdateTaskInput): Task | undefined {
    const task = this.#tasks.get(id)
    if (!task) return undefined

    const updated: Task = {
      ...task,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.completed !== undefined ? { completed: input.completed } : {}),
      ...(input.priority !== undefined ? { priority: input.priority } : {}),
      updatedAt: new Date().toISOString(),
    }
    this.#tasks.set(id, updated)
    return updated
  }

  delete(id: string): Task | undefined {
    const task = this.#tasks.get(id)
    if (!task) return undefined
    this.#tasks.delete(id)
    return task
  }
}

import { PRIORITIES, type Priority, type TaskFilter } from './store'

export const MAX_TITLE_LENGTH = 120

export type Valid<T> = { ok: true; value: T }
export type Invalid = { ok: false; errors: string[] }
export type Result<T> = Valid<T> | Invalid

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Reads the request body as JSON, or `undefined` when it isn't valid JSON. */
export async function readJson(c: { req: { json(): Promise<unknown> } }): Promise<unknown | undefined> {
  try {
    return await c.req.json()
  } catch {
    return undefined
  }
}

/** Validates a `title` value, returning the normalised title or an error message. */
export function parseTitle(value: unknown): { ok: true; value: string } | { ok: false; error: string } {
  if (typeof value !== 'string') return { ok: false, error: '"title" must be a string' }
  const title = value.trim()
  if (title.length === 0) return { ok: false, error: '"title" must not be empty' }
  if (title.length > MAX_TITLE_LENGTH) {
    return { ok: false, error: `"title" must be at most ${MAX_TITLE_LENGTH} characters` }
  }
  return { ok: true, value: title }
}

function isPriority(value: unknown): value is Priority {
  return PRIORITIES.includes(value as Priority)
}

/** Validates a `priority` value, returning it or an error message. */
export function parsePriority(
  value: unknown,
): { ok: true; value: Priority } | { ok: false; error: string } {
  if (!isPriority(value)) {
    return { ok: false, error: `"priority" must be one of ${PRIORITIES.map((p) => `"${p}"`).join(', ')}` }
  }
  return { ok: true, value }
}

export type CreateTaskBody = {
  title: string
  completed?: boolean
  priority?: Priority
}

export type UpdateTaskBody = {
  title?: string
  completed?: boolean
  priority?: Priority
}

/** Validates the body of `POST /tasks`. */
export function parseCreateTaskBody(body: unknown): Result<CreateTaskBody> {
  if (!isPlainObject(body)) {
    return { ok: false, errors: [] }
  }

  const title = parseTitle(body.title)
  if (!title.ok) {
    return { ok: false, errors: [title.error] }
  }

  if (body.completed !== undefined && typeof body.completed !== 'boolean') {
    return { ok: false, errors: ['"completed" must be a boolean'] }
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsed = parsePriority(body.priority)
    if (!parsed.ok) return { ok: false, errors: [parsed.error] }
    priority = parsed.value
  }

  const unknownFields = rejectUnknownFields(body, ['title', 'completed', 'priority'])
  if (unknownFields.length > 0) return { ok: false, errors: unknownFields }

  return {
    ok: true,
    value: { title: title.value, completed: body.completed as boolean | undefined, priority },
  }
}

/** Validates the body of `PATCH /tasks/:id`. */
export function parseUpdateTaskBody(body: unknown): Result<UpdateTaskBody> {
  if (!isPlainObject(body)) {
    return { ok: false, errors: [] }
  }

  const errors: string[] = []
  let title: string | undefined

  if (body.title !== undefined) {
    const parsed = parseTitle(body.title)
    if (parsed.ok) title = parsed.value
    else errors.push(parsed.error)
  }

  if (body.completed !== undefined && typeof body.completed !== 'boolean') {
    errors.push('"completed" must be a boolean')
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsed = parsePriority(body.priority)
    if (parsed.ok) priority = parsed.value
    else errors.push(parsed.error)
  }

  if (body.title === undefined && body.completed === undefined && body.priority === undefined) {
    errors.push('At least one of "title", "completed" or "priority" must be provided')
  }

  errors.push(...rejectUnknownFields(body, ['title', 'completed', 'priority']))

  if (errors.length > 0) return { ok: false, errors }

  return { ok: true, value: { title, completed: body.completed as boolean | undefined, priority } }
}

/**
 * Any field that isn't part of the task payload is invalid input; in particular
 * the former `"done"` field, which `"completed"` replaced.
 */
function rejectUnknownFields(body: Record<string, unknown>, allowed: string[]): string[] {
  return Object.keys(body)
    .filter((key) => !allowed.includes(key))
    .map((key) =>
      key === 'done'
        ? '"done" is not a task field; use "completed"'
        : `"${key}" is not a task field`,
    )
}

/** Validates the query filters of `GET /tasks`. */
export function parseTaskFilter(query: Record<string, string | undefined>): Result<TaskFilter> {
  const errors: string[] = []
  const filter: TaskFilter = {}

  const completed = query.completed
  if (completed !== undefined) {
    if (completed === 'true') filter.completed = true
    else if (completed === 'false') filter.completed = false
    else errors.push('"completed" must be "true" or "false"')
  }

  const priority = query.priority
  if (priority !== undefined) {
    const parsed = parsePriority(priority)
    if (parsed.ok) filter.priority = parsed.value
    else errors.push(parsed.error)
  }

  if (errors.length > 0) return { ok: false, errors }
  return { ok: true, value: filter }
}

import { PRIORITIES, type Priority, type TaskFilter } from './store'

export const MAX_TITLE_LENGTH = 120

/** A rejected payload: the message, plus the per-field details when there are any. */
export type Invalid = { ok: false; message: string; details?: string[] }
export type Result<T> = { ok: true; value: T } | Invalid

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Reads the request body as JSON, or `undefined` when it isn't valid JSON. */
export async function readJson(c: {
  req: { json(): Promise<unknown> }
}): Promise<unknown | undefined> {
  try {
    return await c.req.json()
  } catch {
    return undefined
  }
}

/** Validates a `title` value, returning the normalised title or an error message. */
export function parseTitle(
  value: unknown,
): { ok: true; value: string } | { ok: false; error: string } {
  if (typeof value !== 'string') return { ok: false, error: '"title" must be a string' }
  const title = value.trim()
  if (title.length === 0) return { ok: false, error: '"title" must not be empty' }
  if (title.length > MAX_TITLE_LENGTH) {
    return { ok: false, error: `"title" must be at most ${MAX_TITLE_LENGTH} characters` }
  }
  return { ok: true, value: title }
}

const PRIORITY_ERROR = `"priority" must be one of ${PRIORITIES.map((p) => `"${p}"`).join(', ')}`

/** Validates a `priority` value, returning it or an error message. */
export function parsePriority(
  value: unknown,
): { ok: true; value: Priority } | { ok: false; error: string } {
  if (!PRIORITIES.includes(value as Priority)) return { ok: false, error: PRIORITY_ERROR }
  return { ok: true, value: value as Priority }
}

/**
 * `"done"` was renamed to `"completed"`, so a body still carrying it is invalid
 * input rather than a field to ignore.
 */
const DONE_ERROR = '"done" is not a task field; use "completed" instead'

export type CreateTaskBody = {
  title: string
  completed?: boolean
  priority?: Priority
}

export type UpdateTaskBody = {
  title?: string
  completed?: boolean
  priority?: Priority
}

/** Validates the body of `POST /tasks`. */
export function parseCreateTaskBody(body: unknown): Result<CreateTaskBody> {
  if (!isPlainObject(body)) {
    return { ok: false, message: 'Request body must be a JSON object' }
  }

  const title = parseTitle(body.title)
  if (!title.ok) {
    return { ok: false, message: 'Invalid task payload', details: [title.error] }
  }

  if (body.done !== undefined) {
    return { ok: false, message: 'Invalid task payload', details: [DONE_ERROR] }
  }

  if (body.completed !== undefined && typeof body.completed !== 'boolean') {
    return { ok: false, message: 'Invalid task payload', details: ['"completed" must be a boolean'] }
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsed = parsePriority(body.priority)
    if (!parsed.ok) {
      return { ok: false, message: 'Invalid task payload', details: [parsed.error] }
    }
    priority = parsed.value
  }

  return {
    ok: true,
    value: { title: title.value, completed: body.completed as boolean | undefined, priority },
  }
}

/** Validates the body of `PATCH /tasks/:id`. */
export function parseUpdateTaskBody(body: unknown): Result<UpdateTaskBody> {
  if (!isPlainObject(body)) {
    return { ok: false, message: 'Request body must be a JSON object' }
  }

  const details: string[] = []
  let title: string | undefined

  if (body.title !== undefined) {
    const parsed = parseTitle(body.title)
    if (parsed.ok) title = parsed.value
    else details.push(parsed.error)
  }

  if (body.done !== undefined) {
    details.push(DONE_ERROR)
  }

  if (body.completed !== undefined && typeof body.completed !== 'boolean') {
    details.push('"completed" must be a boolean')
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsed = parsePriority(body.priority)
    if (parsed.ok) priority = parsed.value
    else details.push(parsed.error)
  }

  if (body.title === undefined && body.completed === undefined && body.priority === undefined) {
    details.push('At least one of "title", "completed" or "priority" must be provided')
  }

  if (details.length > 0) {
    return { ok: false, message: 'Invalid task payload', details }
  }

  return { ok: true, value: { title, completed: body.completed as boolean | undefined, priority } }
}

/** Validates the query filters of `GET /tasks`. */
export function parseTaskFilter(query: Record<string, string | undefined>): Result<TaskFilter> {
  const details: string[] = []
  const filter: TaskFilter = {}

  if (query.completed !== undefined) {
    if (query.completed === 'true') filter.completed = true
    else if (query.completed === 'false') filter.completed = false
    else details.push('"completed" must be "true" or "false"')
  }

  if (query.priority !== undefined) {
    const parsed = parsePriority(query.priority)
    if (parsed.ok) filter.priority = parsed.value
    else details.push(parsed.error)
  }

  if (details.length > 0) {
    return { ok: false, message: 'Invalid query parameters', details }
  }
  return { ok: true, value: filter }
}

import { Hono } from 'hono'
import { TaskStore, type Task } from './store'
import {
  parseCreateTaskBody,
  parseTaskFilter,
  parseUpdateTaskBody,
  readJson,
} from './validation'

type Variables = {
  store: TaskStore
}

function badRequest(message: string, details?: string[]) {
  return { error: { code: 'bad_request', message, ...(details ? { details } : {}) } }
}

function notFound(id: string) {
  return { error: { code: 'not_found', message: `Task '${id}' not found` } }
}

export function createApp(store: TaskStore = new TaskStore()) {
  const app = new Hono<{ Variables: Variables }>()

  app.get('/', (c) => {
    return c.text('Hello Hono!')
  })

  app.post('/tasks', async (c) => {
    const parsed = parseCreateTaskBody(await readJson(c))
    if (!parsed.ok) {
      return c.json(badRequest(parsed.message, parsed.details), 400)
    }

    const task: Task = store.create(parsed.value)
    return c.json(task, 201)
  })

  app.get('/tasks', (c) => {
    const filter = parseTaskFilter(c.req.query())
    if (!filter.ok) {
      return c.json(badRequest(filter.message, filter.details), 400)
    }

    return c.json(store.list(filter.value))
  })

  app.get('/tasks/:id', (c) => {
    const id = c.req.param('id')
    const task = store.get(id)
    if (!task) return c.json(notFound(id), 404)
    return c.json(task)
  })

  app.patch('/tasks/:id', async (c) => {
    const id = c.req.param('id')

    const parsed = parseUpdateTaskBody(await readJson(c))
    if (!parsed.ok) {
      return c.json(badRequest(parsed.message, parsed.details), 400)
    }

    // Validation passed, so a missing task is the only remaining failure mode.
    const updated = store.update(id, parsed.value)
    if (!updated) return c.json(notFound(id), 404)
    return c.json(updated)
  })

  app.delete('/tasks/:id', (c) => {
    const id = c.req.param('id')
    const deleted = store.delete(id)
    if (!deleted) return c.json(notFound(id), 404)
    return c.body(null, 204)
  })

  return app
}

